/* questions/maths.js — Maths ASSESSMENT questions, grouped module → topic → level.

   Grouped module → topic → level; the ids must match js/data.js
   (e.g. operations → multiplication → level2). Each assessment picks 10
   questions at random from the level's bank — an even mix of the question
   types (the `cat` codes), in a random order — so it's different every time.

   Question formats:
   1. Multiple choice — `answer` is the index of the right option (0-based).
      Options are shuffled each time, so their order here doesn't matter —
      unless the question has `fixedOrder: true` (e.g. always Odd, then Even).
        { q: "What is 46 + 35?", options: ["81", "71", "711", "82"], answer: 0, cat: "ADD2" }
   2. Typed answer — { typed: true, q: "... ___ ...", word: "632" }
      When every accepted answer is a number, decimal or fraction (e.g. "3/8"),
      the child gets a NUMBER PAD; otherwise a letter keyboard.
      `alt: ["..."]` lists other accepted answers.
   3. Put in order — { order: "asc" (or "desc"), items: ["60", "50", "19"], q: "…", word: "19 < 50 < 60" }
      The child taps the numbers into the answer row; the right order is worked
      out from `items` (`q` and `word` are what the reports show).
   4. Pictures — add `visual: "<svg …>…</svg>"` to show a drawing above the
      question (shapes for perimeter, scales for mass…), or `clock: "h:mm"`
      to show a clock face at that time. A digital time as a typed answer
      gets the number pad with a ":" key. `bar: "7/9"` or `circle: "7/9"`
      draws a fraction picture with 7 of its 9 equal parts shaded; a typed
      fraction answer gets a "/" key and must match exactly (2/4 isn't 1/2).

   Optional on any question:
     cat:     short code used by the Progress report's "weak areas"
              (name it nicely with catLabels on the level in data.js)
     explain: shown after a wrong answer                                    */
window.QUESTIONS = window.QUESTIONS || {};
